def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, allow_abbrev=False)
    parser.add_argument("requirement_dir", type=Path, help="Directory containing requirements.yaml and reference images")
    parser.add_argument("--output-dir", type=Path, required=True, help="Website-provided app output directory")
    args = parser.parse_args(argv)

    base_url = os.environ.get("OPENAI_BASE_URL")
    api_key = os.environ.get("OPENAI_API_KEY")
    if not base_url or not api_key:
        parser.error("The ARCbench runner must provide OPENAI_BASE_URL and OPENAI_API_KEY")
    input_dir = args.requirement_dir.resolve()
    requirements_file = input_dir / "requirements.yaml"
    if not input_dir.is_dir() or not requirements_file.is_file():
        parser.error(f"Expected a directory containing requirements.yaml: {input_dir}")
    if not TEMPLATE_DIR.is_dir() or not (TEMPLATE_DIR / "deploy.sh").is_file():
        parser.error("Upload package is missing templates/deploy.sh")
    node_version, validation_note = check_node_runtime()

    output_dir = args.output_dir.resolve()
    output_dir.mkdir(parents=True, exist_ok=True)
    shutil.copytree(TEMPLATE_DIR, output_dir, dirs_exist_ok=True)
    task_text, images = load_task(requirements_file)
    sources = source_scenarios(yaml.safe_load(requirements_file.read_text(encoding="utf-8-sig")))
    ui_contract_file = output_dir / ".arcbench-ui-contract.json"
    if len(sources) <= 3:
        descriptions = [source_text(source.get("requirement")) for source in sources.values()]
        descriptions += [source_text(parent.get("description")) for source in sources.values()
                         for parent in source.get("shared_context", [])]
        names = {target.get("name") or target.get("label") for description in descriptions for target in controls(description)}
        ui_contract_file.write_text(json.dumps({"names": sorted(names)}, ensure_ascii=False), encoding="utf-8")
    else:
        ui_contract_file.unlink(missing_ok=True)
    user_content: list[dict] = [{"type": "text", "text": task_text + semantic_manifest(sources)}]
    for image_id, image_path in images:
        user_content.extend([
            {"type": "text", "text": f"Reference image {image_id} ({image_path.name}):"},
            image_content(image_path),
        ])

    client = OpenAI(base_url=base_url, api_key=api_key, timeout=600, max_retries=2)
    started = time.monotonic()
    log(f"agent {AGENT_VERSION}; compiling {input_dir.name} with {MODEL}; {len(images)} reference image(s); "
              f"requirements {len(task_text)} character(s); node {node_version or 'unknown'})")
    cases, contract_errors, plan_calls = independent_contracts(client, task_text, sources)
    (output_dir / ".arcbench-browser-cases.json").write_text(
        json.dumps(cases, indent=2, ensure_ascii=False), encoding="utf-8")
    generation_system = SMALL_GENERATION_SYSTEM if len(sources) <= 3 else SYSTEM
    prefix = [{"role": "system", "content": generation_system}, {"role": "user", "content": user_content}]
    data_instruction = (DATA_INSTRUCTION + SESSION_DATA_INSTRUCTION if len(sources) > 3
                        else SMALL_DATA_INSTRUCTION.rstrip())
    proposal, usage = request_files(client, prefix + [{"role": "user", "content": data_instruction}], "data")
    written = write_files(output_dir, proposal["files"])
    all_written = set(written)
    log(f"data pass wrote {len(written)} file(s); compiling the interface pass")
    ui_instruction = LAYOUT_INSTRUCTION if len(sources) > 3 else UI_INSTRUCTION
    if len(sources) <= 3:
        from playwright.sync_api import sync_playwright
    except ImportError:
        return None, "playwright Python package is unavailable"
    try:
        driver = sync_playwright().start()
    except Exception as error:
        return None, f"Playwright driver unavailable: {str(error)[:500]}"
    try:
